#endif


extension FfiAudioTrack: Equatable, Hashable {
    public static func ==(lhs: FfiAudioTrack, rhs: FfiAudioTrack) -> Bool {
        if lhs.languageCode != rhs.languageCode {
            return false
        }
        if lhs.displayName != rhs.displayName {
            return false
        }
        if lhs.isOriginal != rhs.isOriginal {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(languageCode)
        hasher.combine(displayName)
        hasher.combine(isOriginal)
    }
