        }
        if lhs.commentCountText != rhs.commentCountText {
            return false
        }
        if lhs.liveChatTopToken != rhs.liveChatTopToken {
            return false
        }
        if lhs.liveChatAllToken != rhs.liveChatAllToken {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(title)
        hasher.combine(viewsText)
        hasher.combine(dateText)
        hasher.combine(likesText)
        hasher.combine(description)
        hasher.combine(channel)
        hasher.combine(isSubscribed)
        hasher.combine(userRating)
        hasher.combine(isLive)
        hasher.combine(chapters)
        hasher.combine(heatmap)
