        hasher.combine(votes)
        hasher.combine(related)
        hasher.combine(relatedContinuation)
        hasher.combine(commentsToken)
        hasher.combine(commentsTopToken)
        hasher.combine(commentsNewestToken)
        hasher.combine(commentCountText)
        hasher.combine(liveChatTopToken)
        hasher.combine(liveChatAllToken)
    }
